select i.inventory_id as inventoryId, i.warehouse_id as warehouseId, i.product_id as productId, i.model_id as modelId, i.total_quantity as totalQuantity, i.available_quantity as availableQuantity, i.reserved_quantity as reservedQuantity, i.rented_quantity as rentedQuantity, i.repairing_quantity as repairingQuantity, i.damaged_quantity as damagedQuantity, i.stock_protection_qty as stockProtectionQty, i.calculation_mode as calculationMode, i.calculation_percent as calculationPercent, case when i.calculation_mode = 2 then least(i.available_quantity, floor(i.total_quantity * i.calculation_percent / 100)) else greatest(i.available_quantity - i.stock_protection_qty, 0) end as orderableQuantity, i.status, p.product_code as productCode, p.product_name as productName, p.class_id as classId, p.product_type as productType, p.stock_mode as stockMode, p.brand, p.model_name as modelName, w.warehouse_code as warehouseCode, w.warehouse_name as warehouseName, w.city as warehouseCity, w.address as warehouseAddress from ry_business.ry_rental_merchant_inventory i left join ry_business.ry_rental_product p on p.product_id = i.product_id and p.tenant_id = i.tenant_id and p.member_id = i.member_id and p.is_delete = 0 left join ry_business.ry_rental_warehouse w on w.warehouse_id = i.warehouse_id and w.tenant_id = i.tenant_id and w.member_id = i.member_id and w.is_delete = 0 where i.tenant_id = #{tenantId} and i.member_id = #{memberId} and i.is_delete = 0 and (p.product_code like concat('%', #{keyword}, '%') or p.product_name like concat('%', #{keyword}, '%')) and i.warehouse_id = #{warehouseId} and i.warehouse_id <> #{excludeWarehouseId} and exists (select 1 from ry_business.ry_rental_merchant_inventory_unit u where u.inventory_id = i.inventory_id and u.unit_status = #{unitStatus} and u.is_delete = 0) and p.class_id = #{classId} and p.product_type = #{productType} and p.brand = #{brand}
and i.warehouse_id in #{allowedWarehouseId}
and 1 = 0
order by i.create_time desc, i.inventory_id desc

select p.product_id as productId, p.product_code as productCode, p.product_name as productName, p.class_id as classId, p.product_type as productType, p.stock_mode as stockMode, p.brand, p.model_name as modelName from ry_business.ry_rental_product p where p.tenant_id = #{tenantId} and p.member_id = #{memberId} and p.is_delete = 0 and p.status = 0 and p.class_id = #{classId} and p.product_type = #{productType} and p.brand = #{brand}
and (p.product_code like concat('%', #{keyword}, '%') or p.product_name like concat('%', #{keyword}, '%') or p.model_name like concat('%', #{keyword}, '%'))
order by p.product_type, p.product_name, p.product_id desc

with shipment_rows as ( select date(coalesce(o.ship_due_time, o.lease_start_date)) as trendDate, case when #{mode} = 'package' then oi.package_id else coalesce(p.model_id, package_row.model_id) end as itemId, case when #{mode} = 'package' then package_row.package_name else coalesce(nullif(p.model_name, ''), model_option.model_name, '未命名型号') end as itemName, case when #{mode} = 'package' then null else coalesce(nullif(p.brand, ''), model_option.brand) end as itemBrand, case when #{mode} = 'package' then package_row.package_code else null end as itemCode, sum(coalesce(oi.quantity, 1)) as shipQuantity, cast(0 as signed) as returnQuantity, cast(0 as signed) as estimatedShipQuantity, cast(0 as signed) as estimatedReturnQuantity from ry_business.ry_rental_order o inner join ry_business.ry_rental_order_item oi on oi.order_id = o.order_id and oi.tenant_id = o.tenant_id and oi.member_id = o.member_id and oi.is_delete = 0 left join ry_business.ry_rental_product p on p.product_id = oi.product_id and p.tenant_id = oi.tenant_id and p.member_id = oi.member_id and p.is_delete = 0 left join ry_business.ry_rental_merchant_package package_row on package_row.package_id = oi.package_id and package_row.tenant_id = oi.tenant_id and package_row.member_id = oi.member_id and package_row.is_delete = 0 left join ( select tenant_id, member_id, model_id, max(nullif(model_name, '')) as model_name, max(nullif(brand, '')) as brand from ry_business.ry_rental_product where tenant_id = #{tenantId} and member_id = #{memberId} and is_delete = 0 and model_id is not null group by tenant_id, member_id, model_id ) model_option on model_option.tenant_id = o.tenant_id and model_option.member_id = o.member_id and model_option.model_id = coalesce(p.model_id, package_row.model_id) where o.tenant_id = #{tenantId} and o.member_id = #{memberId} and o.is_delete = 0 and o.order_status in #{status} and ((o.ship_due_time >= current_date and o.ship_due_time < date_add(current_date, interval #{days} day)) or (o.ship_due_time is null and o.lease_start_date >= current_date and o.lease_start_date < date_add(current_date, interval #{days} day))) and o.warehouse_id = #{warehouseId}
and o.warehouse_id in #{allowedWarehouseId}
and 1 = 0
and oi.package_id is not null and coalesce(p.model_id, package_row.model_id) is not null
and coalesce(p.model_id, package_row.model_id) = #{modelId} and coalesce(nullif(p.brand, ''), model_option.brand) = #{brand} group by trendDate, itemId, itemName, itemBrand, itemCode ), return_rows as ( select date(coalesce(o.return_due_time, o.lease_end_date)) as trendDate, case when #{mode} = 'package' then oi.package_id else coalesce(p.model_id, package_row.model_id) end as itemId, case when #{mode} = 'package' then package_row.package_name else coalesce(nullif(p.model_name, ''), model_option.model_name, '未命名型号') end as itemName, case when #{mode} = 'package' then null else coalesce(nullif(p.brand, ''), model_option.brand) end as itemBrand, case when #{mode} = 'package' then package_row.package_code else null end as itemCode, cast(0 as signed) as shipQuantity, sum(coalesce(oi.quantity, 1)) as returnQuantity, cast(0 as signed) as estimatedShipQuantity, cast(0 as signed) as estimatedReturnQuantity from ry_business.ry_rental_order o inner join ry_business.ry_rental_order_item oi on oi.order_id = o.order_id and oi.tenant_id = o.tenant_id and oi.member_id = o.member_id and oi.is_delete = 0 left join ry_business.ry_rental_product p on p.product_id = oi.product_id and p.tenant_id = oi.tenant_id and p.member_id = oi.member_id and p.is_delete = 0 left join ry_business.ry_rental_merchant_package package_row on package_row.package_id = oi.package_id and package_row.tenant_id = oi.tenant_id and package_row.member_id = oi.member_id and package_row.is_delete = 0 left join ( select tenant_id, member_id, model_id, max(nullif(model_name, '')) as model_name, max(nullif(brand, '')) as brand from ry_business.ry_rental_product where tenant_id = #{tenantId} and member_id = #{memberId} and is_delete = 0 and model_id is not null group by tenant_id, member_id, model_id ) model_option on model_option.tenant_id = o.tenant_id and model_option.member_id = o.member_id and model_option.model_id = coalesce(p.model_id, package_row.model_id) where o.tenant_id = #{tenantId} and o.member_id = #{memberId} and o.is_delete = 0 and o.order_status in #{status} and ((o.return_due_time >= current_date and o.return_due_time < date_add(current_date, interval #{days} day)) or (o.return_due_time is null and o.lease_end_date >= current_date and o.lease_end_date < date_add(current_date, interval #{days} day))) and o.return_warehouse_id = #{warehouseId}
and o.return_warehouse_id in #{allowedWarehouseId}
and 1 = 0
and oi.package_id is not null and coalesce(p.model_id, package_row.model_id) is not null
and coalesce(p.model_id, package_row.model_id) = #{modelId} and coalesce(nullif(p.brand, ''), model_option.brand) = #{brand} group by trendDate, itemId, itemName, itemBrand, itemCode ), route_rows as ( select l.*, row_number() over ( partition by l.tenant_id, l.member_id, l.order_id, l.direction order by l.create_time desc, l.logistics_id desc ) as routeRank from ry_business.ry_rental_logistics_order l where l.tenant_id = #{tenantId} and l.member_id = #{memberId} and l.is_delete = 0 ), route_ship_rows as ( select date(l.pickup_time) as trendDate, case when #{mode} = 'package' then oi.package_id else coalesce(p.model_id, package_row.model_id) end as itemId, case when #{mode} = 'package' then package_row.package_name else coalesce(nullif(p.model_name, ''), model_option.model_name, '未命名型号') end as itemName, case when #{mode} = 'package' then null else coalesce(nullif(p.brand, ''), model_option.brand) end as itemBrand, case when #{mode} = 'package' then package_row.package_code else null end as itemCode, cast(0 as signed) as shipQuantity, cast(0 as signed) as returnQuantity, sum(coalesce(oi.quantity, 1)) as estimatedShipQuantity, cast(0 as signed) as estimatedReturnQuantity from route_rows l inner join ry_business.ry_rental_order o on o.order_id = l.order_id and o.tenant_id = l.tenant_id and o.member_id = l.member_id and o.is_delete = 0 inner join ry_business.ry_rental_order_item oi on oi.order_id = o.order_id and oi.tenant_id = o.tenant_id and oi.member_id = o.member_id and oi.is_delete = 0 left join ry_business.ry_rental_product p on p.product_id = oi.product_id and p.tenant_id = oi.tenant_id and p.member_id = oi.member_id and p.is_delete = 0 left join ry_business.ry_rental_merchant_package package_row on package_row.package_id = oi.package_id and package_row.tenant_id = oi.tenant_id and package_row.member_id = oi.member_id and package_row.is_delete = 0 left join ( select tenant_id, member_id, model_id, max(nullif(model_name, '')) as model_name, max(nullif(brand, '')) as brand from ry_business.ry_rental_product where tenant_id = #{tenantId} and member_id = #{memberId} and is_delete = 0 and model_id is not null group by tenant_id, member_id, model_id ) model_option on model_option.tenant_id = o.tenant_id and model_option.member_id = o.member_id and model_option.model_id = coalesce(p.model_id, package_row.model_id) where l.routeRank = 1 and l.direction = 1 and l.pickup_time >= current_date and l.pickup_time < date_add(current_date, interval #{days} day) and coalesce(l.route_status, 0) not in (2, 4) and coalesce(l.warehouse_id, o.warehouse_id) = #{warehouseId}
and coalesce(l.warehouse_id, o.warehouse_id) in #{allowedWarehouseId}
and 1 = 0
and oi.package_id is not null and coalesce(p.model_id, package_row.model_id) is not null
and coalesce(p.model_id, package_row.model_id) = #{modelId} and coalesce(nullif(p.brand, ''), model_option.brand) = #{brand} group by trendDate, itemId, itemName, itemBrand, itemCode ), route_return_rows as ( select date(l.estimated_arrive_time) as trendDate, case when #{mode} = 'package' then oi.package_id else coalesce(p.model_id, package_row.model_id) end as itemId, case when #{mode} = 'package' then package_row.package_name else coalesce(nullif(p.model_name, ''), model_option.model_name, '未命名型号') end as itemName, case when #{mode} = 'package' then null else coalesce(nullif(p.brand, ''), model_option.brand) end as itemBrand, case when #{mode} = 'package' then package_row.package_code else null end as itemCode, cast(0 as signed) as shipQuantity, cast(0 as signed) as returnQuantity, cast(0 as signed) as estimatedShipQuantity, sum(coalesce(oi.quantity, 1)) as estimatedReturnQuantity from route_rows l inner join ry_business.ry_rental_order o on o.order_id = l.order_id and o.tenant_id = l.tenant_id and o.member_id = l.member_id and o.is_delete = 0 inner join ry_business.ry_rental_order_item oi on oi.order_id = o.order_id and oi.tenant_id = o.tenant_id and oi.member_id = o.member_id and oi.is_delete = 0 left join ry_business.ry_rental_product p on p.product_id = oi.product_id and p.tenant_id = oi.tenant_id and p.member_id = oi.member_id and p.is_delete = 0 left join ry_business.ry_rental_merchant_package package_row on package_row.package_id = oi.package_id and package_row.tenant_id = oi.tenant_id and package_row.member_id = oi.member_id and package_row.is_delete = 0 left join ( select tenant_id, member_id, model_id, max(nullif(model_name, '')) as model_name, max(nullif(brand, '')) as brand from ry_business.ry_rental_product where tenant_id = #{tenantId} and member_id = #{memberId} and is_delete = 0 and model_id is not null group by tenant_id, member_id, model_id ) model_option on model_option.tenant_id = o.tenant_id and model_option.member_id = o.member_id and model_option.model_id = coalesce(p.model_id, package_row.model_id) where l.routeRank = 1 and l.direction = 2 and l.estimated_arrive_time >= current_date and l.estimated_arrive_time < date_add(current_date, interval #{days} day) and coalesce(l.route_status, 0) not in (2, 4) and coalesce(l.warehouse_id, o.return_warehouse_id) = #{warehouseId}
and coalesce(l.warehouse_id, o.return_warehouse_id) in #{allowedWarehouseId}
and 1 = 0
and oi.package_id is not null and coalesce(p.model_id, package_row.model_id) is not null
and coalesce(p.model_id, package_row.model_id) = #{modelId} and coalesce(nullif(p.brand, ''), model_option.brand) = #{brand} group by trendDate, itemId, itemName, itemBrand, itemCode ) select trendDate, itemId, itemName, itemBrand, itemCode, sum(shipQuantity) as shipQuantity, sum(returnQuantity) as returnQuantity, sum(estimatedShipQuantity) as estimatedShipQuantity, sum(estimatedReturnQuantity) as estimatedReturnQuantity from ( select trendDate, itemId, itemName, itemBrand, itemCode, shipQuantity, returnQuantity, estimatedShipQuantity, estimatedReturnQuantity from shipment_rows union all select trendDate, itemId, itemName, itemBrand, itemCode, shipQuantity, returnQuantity, estimatedShipQuantity, estimatedReturnQuantity from return_rows union all select trendDate, itemId, itemName, itemBrand, itemCode, shipQuantity, returnQuantity, estimatedShipQuantity, estimatedReturnQuantity from route_ship_rows union all select trendDate, itemId, itemName, itemBrand, itemCode, shipQuantity, returnQuantity, estimatedShipQuantity, estimatedReturnQuantity from route_return_rows ) movements group by trendDate, itemId, itemName, itemBrand, itemCode
union all
select cast(null as date) as trendDate, p.package_id as itemId, p.package_name as itemName, cast(null as char) as itemBrand, p.package_code as itemCode, cast(0 as signed) as shipQuantity, cast(0 as signed) as returnQuantity, cast(0 as signed) as estimatedShipQuantity, cast(0 as signed) as estimatedReturnQuantity from ry_business.ry_rental_merchant_package p where p.tenant_id = #{tenantId} and p.member_id = #{memberId} and p.status = 0 and p.is_delete = 0
select cast(null as date) as trendDate, p.model_id as itemId, coalesce(max(nullif(p.model_name, '')), max(nullif(p.product_name, '')), '未命名型号') as itemName, max(nullif(p.brand, '')) as itemBrand, cast(null as char) as itemCode, cast(0 as signed) as shipQuantity, cast(0 as signed) as returnQuantity, cast(0 as signed) as estimatedShipQuantity, cast(0 as signed) as estimatedReturnQuantity from ry_business.ry_rental_product p where p.tenant_id = #{tenantId} and p.member_id = #{memberId} and p.status = 0 and p.is_delete = 0 and p.model_id is not null and p.model_id = #{modelId} and p.brand = #{brand} group by p.model_id
order by trendDate, itemName

select max(o.order_id) as orderId, max(o.order_no) as orderNo, max(coalesce(nullif(o.customer_nickname, ''), nullif(o.customer_name, ''), '未填写')) as customerName, max(coalesce(nullif(o.recipient_name, ''), '未填写')) as recipientName, max(coalesce(nullif(o.recipient_phone, ''), '未填写')) as recipientPhone, max(case when #{mode} = 'package' then package_row.package_name else coalesce(nullif(p.model_name, ''), model_option.model_name, nullif(p.product_name, ''), '未命名型号') end) as itemName, max(package_row.package_name) as packageName, sum(coalesce(oi.quantity, 1)) as quantity, max(case when #{source} = 'estimated' then trend_warehouse.warehouse_name when #{direction} = 'return' then return_warehouse.warehouse_name else w.warehouse_name end) as warehouseName, max(case when #{source} = 'estimated' and #{direction} = 'ship' then date_format(route.pickup_time, '%Y-%m-%d %H:%i:%s') when #{source} = 'estimated' and #{direction} = 'return' then date_format(route.estimated_arrive_time, '%Y-%m-%d %H:%i:%s') when #{direction} = 'return' then date_format(coalesce(o.return_due_time, o.lease_end_date), '%Y-%m-%d %H:%i:%s') else date_format(coalesce(o.ship_due_time, o.lease_start_date), '%Y-%m-%d %H:%i:%s') end) as trendTime, max(o.order_status) as orderStatus from ry_business.ry_rental_order o inner join ry_business.ry_rental_order_item oi on oi.order_id = o.order_id and oi.tenant_id = o.tenant_id and oi.member_id = o.member_id and oi.is_delete = 0 left join ry_business.ry_rental_product p on p.product_id = oi.product_id and p.tenant_id = oi.tenant_id and p.member_id = oi.member_id and p.is_delete = 0 left join ry_business.ry_rental_merchant_package package_row on package_row.package_id = oi.package_id and package_row.tenant_id = oi.tenant_id and package_row.member_id = oi.member_id and package_row.is_delete = 0 left join ( select tenant_id, member_id, model_id, max(nullif(model_name, '')) as model_name from ry_business.ry_rental_product where tenant_id = #{tenantId} and member_id = #{memberId} and is_delete = 0 and model_id is not null group by tenant_id, member_id, model_id ) model_option on model_option.tenant_id = o.tenant_id and model_option.member_id = o.member_id and model_option.model_id = coalesce(p.model_id, package_row.model_id) left join ry_business.ry_rental_logistics_order route on route.tenant_id = o.tenant_id and route.member_id = o.member_id and route.order_id = o.order_id and route.is_delete = 0 and route.direction = case when #{direction} = 'ship' then 1 else 2 end and route.logistics_id = ( select latest_route.logistics_id from ry_business.ry_rental_logistics_order latest_route where latest_route.tenant_id = o.tenant_id and latest_route.member_id = o.member_id and latest_route.order_id = o.order_id and latest_route.direction = route.direction and latest_route.is_delete = 0 order by latest_route.create_time desc, latest_route.logistics_id desc limit 1 ) left join ry_business.ry_rental_warehouse w on w.warehouse_id = o.warehouse_id and w.tenant_id = o.tenant_id and w.member_id = o.member_id and w.is_delete = 0 left join ry_business.ry_rental_warehouse return_warehouse on return_warehouse.warehouse_id = o.return_warehouse_id and return_warehouse.tenant_id = o.tenant_id and return_warehouse.member_id = o.member_id and return_warehouse.is_delete = 0 left join ry_business.ry_rental_warehouse trend_warehouse on trend_warehouse.warehouse_id = coalesce(route.warehouse_id, case when #{direction} = 'return' then o.return_warehouse_id else o.warehouse_id end) and trend_warehouse.tenant_id = o.tenant_id and trend_warehouse.member_id = o.member_id and trend_warehouse.is_delete = 0 where o.tenant_id = #{tenantId} and o.member_id = #{memberId} and o.is_delete = 0
and route.pickup_time >= #{trendDate} and route.pickup_time < date_add(#{trendDate}, interval 1 day) and coalesce(route.route_status, 0) not in (2, 4)
and route.estimated_arrive_time >= #{trendDate} and route.estimated_arrive_time < date_add(#{trendDate}, interval 1 day) and coalesce(route.route_status, 0) not in (2, 4)
and coalesce(o.return_due_time, o.lease_end_date) >= #{trendDate} and coalesce(o.return_due_time, o.lease_end_date) < date_add(#{trendDate}, interval 1 day) and o.order_status in
#{status}
and coalesce(o.ship_due_time, o.lease_start_date) >= #{trendDate} and coalesce(o.ship_due_time, o.lease_start_date) < date_add(#{trendDate}, interval 1 day) and o.order_status in
#{status}
and oi.package_id = #{itemId}
and coalesce(p.model_id, package_row.model_id) = #{itemId}
and coalesce(route.warehouse_id, o.return_warehouse_id) = #{warehouseId}
and coalesce(route.warehouse_id, o.return_warehouse_id) in
#{allowedWarehouseId}
and 1 = 0
and o.return_warehouse_id = #{warehouseId}
and o.return_warehouse_id in
#{allowedWarehouseId}
and 1 = 0
and coalesce(route.warehouse_id, o.warehouse_id) = #{warehouseId}
and coalesce(route.warehouse_id, o.warehouse_id) in
#{allowedWarehouseId}
and 1 = 0
and o.warehouse_id = #{warehouseId}
and o.warehouse_id in
#{allowedWarehouseId}
and 1 = 0
group by o.order_id order by trendTime asc, orderNo asc

select count(distinct o.order_id) from ry_business.ry_rental_order o inner join ry_business.ry_rental_order_item oi on oi.order_id = o.order_id and oi.tenant_id = o.tenant_id and oi.member_id = o.member_id and oi.is_delete = 0 left join ry_business.ry_rental_product p on p.product_id = oi.product_id and p.tenant_id = oi.tenant_id and p.member_id = oi.member_id and p.is_delete = 0 left join ry_business.ry_rental_merchant_package package_row on package_row.package_id = oi.package_id and package_row.tenant_id = oi.tenant_id and package_row.member_id = oi.member_id and package_row.is_delete = 0 left join ( select tenant_id, member_id, model_id, max(nullif(model_name, '')) as model_name, max(nullif(brand, '')) as brand from ry_business.ry_rental_product where tenant_id = #{tenantId} and member_id = #{memberId} and is_delete = 0 and model_id is not null group by tenant_id, member_id, model_id ) model_option on model_option.tenant_id = o.tenant_id and model_option.member_id = o.member_id and model_option.model_id = coalesce(p.model_id, package_row.model_id) where o.tenant_id = #{tenantId} and o.member_id = #{memberId} and o.is_delete = 0 and o.order_status in #{status} and o.warehouse_id = #{warehouseId}
and o.warehouse_id in #{allowedWarehouseId}
and 1 = 0
and oi.package_id is not null and coalesce(p.model_id, package_row.model_id) is not null
and coalesce(p.model_id, package_row.model_id) = #{modelId} and coalesce(nullif(p.brand, ''), model_option.brand) = #{brand}

select u.unit_id as unitId, u.inventory_id as inventoryId, u.product_id as productId, u.warehouse_id as warehouseId, u.model_id as modelId, u.unit_code as unitCode, u.serial_number as serialNumber, u.unit_status as unitStatus, u.condition_level as conditionLevel, u.memory_spec as memorySpec, u.purchase_cost as purchaseCost, date_format(u.insurance_until, '%Y-%m-%d') as insuranceUntil, u.insurance_amount as insuranceAmount, u.serial_photo_url as serialPhotoUrl, u.market_verified_flag as marketVerifiedFlag, date_format(u.market_verified_time, '%Y-%m-%d %H:%i:%s') as marketVerifiedTime, u.remark, u.source_batch_id as sourceBatchId, p.product_name as productName, p.model_name as modelName, w.warehouse_name as warehouseName, case when exists ( select 1 from ry_business.ry_rental_merchant_inventory_reservation_unit ru inner join ry_business.ry_rental_merchant_inventory_reservation r on r.reservation_id = ru.reservation_id and r.tenant_id = u.tenant_id and r.member_id = u.member_id and r.order_id is not null where ru.unit_id = u.unit_id and ru.is_delete = 0 and r.is_delete = 0 ) or exists ( select 1 from ry_business.ry_rental_order_item oi where oi.tenant_id = u.tenant_id and oi.member_id = u.member_id and oi.sn_id = u.unit_id and oi.is_delete = 0 ) or exists ( select 1 from ry_business.ry_rental_order o where o.tenant_id = u.tenant_id and o.member_id = u.member_id and o.is_delete = 0 and json_search(coalesce(o.package_details_json, json_object()), 'one', cast(u.unit_id as char), null, '$.items[*].unitIds[*]') is not null ) then 1 else 0 end as orderAssociated from ry_business.ry_rental_merchant_inventory_unit u left join ry_business.ry_rental_product p on p.product_id = u.product_id and p.tenant_id = u.tenant_id and p.member_id = u.member_id and p.is_delete = 0 left join ry_business.ry_rental_warehouse w on w.warehouse_id = u.warehouse_id and w.tenant_id = u.tenant_id and w.member_id = u.member_id and w.is_delete = 0 where u.tenant_id = #{tenantId} and u.member_id = #{memberId} and u.is_delete = 0 and u.inventory_id = #{inventoryId} and u.product_id = #{productId} and u.warehouse_id = #{warehouseId}
and (u.unit_code like concat('%', #{keyword}, '%') or u.serial_number like concat('%', #{keyword}, '%'))
and u.unit_status = #{unitStatus}
and not ( exists ( select 1 from ry_business.ry_rental_merchant_inventory_reservation_unit ru inner join ry_business.ry_rental_merchant_inventory_reservation r on r.reservation_id = ru.reservation_id and r.tenant_id = u.tenant_id and r.member_id = u.member_id and r.order_id is not null where ru.unit_id = u.unit_id and ru.is_delete = 0 and r.is_delete = 0 ) or exists ( select 1 from ry_business.ry_rental_order_item oi where oi.tenant_id = u.tenant_id and oi.member_id = u.member_id and oi.sn_id = u.unit_id and oi.is_delete = 0 ) or exists ( select 1 from ry_business.ry_rental_order o where o.tenant_id = u.tenant_id and o.member_id = u.member_id and o.is_delete = 0 and json_search(coalesce(o.package_details_json, json_object()), 'one', cast(u.unit_id as char), null, '$.items[*].unitIds[*]') is not null ) )
order by u.unit_id desc

select u.unit_id as unitId, u.unit_code as unitCode, u.serial_number as serialNumber, p.brand, p.model_name as modelName, u.memory_spec as memorySpec, u.condition_level as conditionLevel, w.warehouse_name as warehouseName from ry_business.ry_rental_merchant_inventory_unit u inner join ry_business.ry_rental_product p on p.product_id = u.product_id and p.tenant_id = u.tenant_id and p.member_id = u.member_id and p.is_delete = 0 and p.status = 0 inner join ry_business.ry_rental_warehouse w on w.warehouse_id = u.warehouse_id and w.tenant_id = u.tenant_id and w.member_id = u.member_id and w.is_delete = 0 where u.tenant_id = #{tenantId} and u.member_id = #{memberId} and u.unit_status = 1 and u.market_verified_flag = 1 and u.serial_photo_url is not null and u.serial_photo_url <> '' and u.is_delete = 0 and p.brand = #{brand} and p.model_name = #{modelName}
and coalesce(u.memory_spec, '') = #{memorySpec} and coalesce(u.memory_spec, '') = ''
and u.unit_id in #{unitId}
order by u.unit_id desc

