update ry_business.ry_rental_merchant_inventory_batch
set success_quantity = #{successQuantity}, failed_quantity = #{failedQuantity}, batch_status = #{status}, update_by = #{operator}
where batch_id = #{batchId} and is_delete = 0

update ry_business.ry_rental_merchant_inventory_reservation
set order_id = #{orderId}, update_time = now()
where tenant_id = #{tenantId} and member_id = #{memberId}
  and reservation_id = #{reservationId} and reservation_source = 2
  and external_token_id = #{tokenId} and external_order_no = #{externalOrderNo}
  and reservation_status = 1 and order_id is null and is_delete = 0

