       warehouse_id as warehouseId, unit_code as unitCode, serial_number as serialNumber
from ry_business.ry_rental_merchant_inventory_unit
where tenant_id = #{tenantId} and member_id = #{memberId}
  and product_id = #{productId} and warehouse_id = #{warehouseId}
  and unit_status = 1 and is_delete = 0
order by unit_id
limit #{quantity}
for update

