update ry_business.ry_rental_merchant_inventory_unit
set inventory_id = #{targetInventoryId}, warehouse_id = #{targetWarehouseId},
    update_by = #{operator}, update_time = now(), version = version + 1
where tenant_id = #{tenantId} and member_id = #{memberId} and unit_id = #{unitId}
  and inventory_id = #{sourceInventoryId} and warehouse_id = #{sourceWarehouseId}
  and unit_status = 1 and is_delete = 0

